3	import { useEffect, useRef, ReactNode } from 'react';
4	
5	interface RevealProps {
6	  children: ReactNode;
7	  className?: string;
8	  style?: React.CSSProperties;
9	}
10	
11	export function Reveal({ children, className = '', style }: RevealProps) {
12	  const ref = useRef<HTMLDivElement>(null);
13	
14	  useEffect(() => {
15	    const el = ref.current;
16	    if (!el) return;
17	
18	    const observer = new IntersectionObserver(
19	      ([entry]) => {
20	        if (entry.isIntersecting) {
21	          entry.target.classList.add('in');
22	          observer.unobserve(entry.target);
23	        }
24	      },
25	      { threshold: 0.1 },
26	    );
27	
28	    observer.observe(el);
29	    return () => observer.disconnect();
30	  }, []);
31	
32	  return (
33	    <div ref={ref} className={`reveal ${className}`} style={style}>
34	      {children}
35	    </div>
36	  );
37	}
